"""U220 — Jev RESTART sweep: 40 themes not yet in the pool, each judged on the two exact filters + survey distance."""
import json,sys
sys.path.insert(0,'code'); import jev
T=["additive combinatorics: sumset structure of the set of perfect powers >=3 (Erdos-type sparsity, energy bounds)","sieve-theoretic density: perfect powers have density making a+b=c heuristically finite — make a term-by-term rigorous large sieve",
"Diophantine approximation of log C/log B by z/y: continued-fraction structure forced by A^x small relative","S-unit equations: fix the SET of primes dividing ABC (not the bases) and use the explicit S-unit algorithm",
"polynomial identities: classify all polynomial families f^x+g^y=h^z over Z[t] (Mason-Stothers says none with coprime nonconstant) and specialisation","Galois cohomology: obstruction in H^1 of the mu_x x mu_y x mu_z torsor over the punctured line",
"Brauer-Manin obstruction on the generalized Fermat surface / its torsors","descent via the universal torsor of the orbifold curve (Poonen's approach for (2,3,7)) done uniformly",
"Arakelov intersection on the arithmetic surface of the Frey curve restricted to perfect-power discriminants","Vojta's conjecture for the specific orbifold with proven cases (Faltings for curves of genus>=2: Darmon-Granville finiteness) made effective via Lawrence-Venkatesh",
"Lawrence-Venkatesh p-adic period map for the family of superelliptic covers","Chabauty-Kim nonabelian for the thrice-punctured line with S-integral points where S varies with the solution",
"Runge's method exploiting that two summands are powers","Skolem p-adic method on the exponential equation in exponents for fixed prime support",
"hypergeometric abc by Pade approximants to (1-t)^(1/n) (Bennett's method) applied with both sides powers","Thue-Siegel with the 'both summands are powers' trick giving two independent good approximations",
"transcendence: linear forms in THREE logs x log A, y log B, z log C with integer coefficients being the exponents","ergodic/dynamics: orbit of (A,B,C) under the semigroup generated by power maps on P^2 and unlikely intersections (Zilber-Pink)",
"Zilber-Pink / unlikely intersections for the line a+b=c in G_m^2 meeting the 'power subgroups'","Bombieri-Masser-Zannier bounded height for a+b=1 intersect multiplicative dependence of rank conditions",
"o-minimality / Pila-Wilkie point counting on the definable set {(x log A, ...)}","model theory of Z with exponentiation: definability of the solution set",
"circle method: count solutions of A^x+B^y=C^z with weights and show the coprime main term vanishes","mean values of exponential sums over perfect powers (Vinogradov) for an upper bound of coprime solutions in boxes",
"Ramanujan-Nagell generalisations via Bilu-Hanrot-Voutier primitive divisors of Lucas sequences","primitive divisor theorem (Zsigmondy/BHV) applied to C^z - B^y when y,z share structure",
"Zsigmondy on A^x = C^z - B^y seen as a Lehmer pair when exponents are equal; extension to unequal via lcm","class field theory: the field Q(A^(x/p)) and reciprocity laws (Eisenstein reciprocity as in Wieferich-type criteria for FLT)",
"Wieferich/Furtwangler-type criteria: q^(p-1)=1 mod p^2 conditions for primes q | ABC generalized to three exponents","Kummer-style cyclotomic descent with regular-prime hypothesis for (p,p,r)",
"Stickelberger / Mihailescu's annihilator method (used for Catalan) extended from x^p-y^q=1 to x^p-y^q=z^r","Mihailescu double Wieferich pair analog for three exponents",
"Cassels-type divisibility relations (q | x, p | y in Catalan) generalized to Beal","Runge+Cassels: factor C^z-B^y cyclotomically when gcd(y,z)>1 only",
"tropical/valuative geometry: Newton polygon of a+b=c at every prime simultaneously","Berkovich / adelic equidistribution of small-height points on the line a+b=1",
"Mahler measure/Lehmer-type lower bounds for heights of multiplicatively dependent solutions","K-theory regulators / Bloch group elements from a+b=c (Steinberg symbol {a/c,b/c}=0)",
"Steinberg relation: {A^x/C^z, B^y/C^z}=0 in K_2(Q) gives xy{A,B}+... torsion conditions via tame symbols","tame symbols of the K_2 element at each prime dividing ABC as a system of power-residue conditions"]
CTX="Beal conjecture. Survey lists as FAILED: bounded computation/sieves, signature-by-signature modular method, elementary congruences, abc/Baker-style bounds (ineffective or too weak). Beal is false over Z[i] at one identity tied to ramified 2. Ten coprime solutions exist with an exponent 2."
Q={"dead":jev.noul("Is this theme already known to give at best FINITENESS or results for restricted exponents, not the full conjecture?",true="known limited",false="not known limited"),
 "sep2":jev.noul("Does the theme have a natural reason to behave differently when an exponent equals 2 versus >=3?",true="separates exponent 2",false="blind to exponent 2"),
 "test":jev.noul("Is there a concrete exact computation on known data (Fermat-Catalan solutions, small cases) that would discriminate the idea within an hour?",true="testable",false="not testable"),
 "lit":jev.noul("Did Mihailescu-type cyclotomic/annihilator or K-theoretic methods already get applied to three-term power equations in the literature?",true="already applied",false="not applied")}
rs=jev.ask_many([{"context":CTX,"theme":t} for t in T],Q,concurrency=12)
rows=[]
for t,r in zip(T,rs):
    if 'answers' not in r: continue
    a={k:round(v['noul'],2) for k,v in r['answers'].items()}
    rows.append((round((1-a['dead'])*a['sep2']*a['test'],3),a,t))
rows.sort(key=lambda r:-r[0])
json.dump({"status":"HYPOTHESIS_ONLY","rows":rows},open('research/pool/evidence/theme_sweep_U220.json','w'),indent=1)
for r in rows[:8]: print(r[0],r[1],r[2][:90])
